output = []
for row in range(16):
    out_row = []
    for col in range(26):
        # Check original shape:
        # Top: rows 3-10, cols 2-5
        # Middle-right: rows 7-14, cols 6-9 (horizontal extension)
        # Bottom: rows 11-14, cols 2-9

        # Color mapping:
        # Left/top vertical: 2
        # Middle-right horizontal: 3
        # Bottom horizontal: 4

        should_have_8 = False
        if 3 <= row <= 10 and 2 <= col <= 5:
            should_have_8 = should_have_8 or True  # Top vertical
        if 7 <= row <= 14 and 6 <= col <= 9:
            should_have_8 = should_have_8 or True  # Middle-right horizontal
        if 11 <= row <= 14 and 2 <= col <= 9:
            should_have_8 = should_have_8 or True  # Bottom horizontal

        if should_have_8:
            # Determine color based on dominant position
            if 11 <= row <= 14 and 2 <= col <= 9:
                out_row.append(4)  # Bottom horizontal
            elif 7 <= row <= 10 and 6 <= col <= 9:
                out_row.append(3)  # Middle-right horizontal
            elif row <= 6 and 2 <= col <= 5:
                out_row.append(2)  # Top vertical
            elif 7 <= row <= 10 and 2 <= col <= 5:
                out_row.append(2)  # Vertical continuation
            else:
                out_row.append(2)  # Default to left/top
        else:
            out_row.append(0)
    output.append(out_row)

# Verify the grid
print("Grid:")
for row in output:
    print(row)

